{"output": "def transform(grid):
    # A singleton of the output color is extended to form a contiguous line;
    # the pixels along the extension are recolored, not the full line source.
    from collections import Counter
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # In the examples, a target-color singleton and an axis-aligned segment
    # of a different foreground color encode the segment's extension line.
    # Test orientation and select the isolated single cell lying on the line.
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg: continue
            # horizontal/vertical runs of color length >=2, infer aligned singleton
            for dr,dc in ((1,0),(0,1)):
                run=[]
                rr,cc=r,c
                while 0<=rr<h and 0<=cc<w and grid[rr][cc]==color:
                    run.append((rr,cc)); rr+=dr; cc+=dc
                if len(run)<2: continue
                # a singleton other-color point collinear with run is the target
                for tr,tc in ((run[0][0]-dr,run[0][1]-dc),(rr,cc)):
                    if 0<=tr<h and 0<=tc<w and grid[tr][tc]!=bg and grid[tr][tc]!=color:
                        target=grid[tr][tc]
                        # Recolor all cells between that marker and run end, inclusive of marker.
                        y,x=tr,tc
                        while 0<=y<h and 0<=x<w and grid[y][x]!=bg and grid[y][x]!=color:
                            out[y][x]=target; y+=dr; x+=dc
    return out", "exit_code": 0, "error": null}

